import argparse
import json
import subprocess
import requests
import sys
from xml.etree import ElementTree as ET

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    services = {}
    for service in root.findall('service'):
        name = service.get('name').strip()
        command = service.find('command').text.strip()
        url = service.find('url').text.strip()
        services[name] = {'command': command, 'url': url}
    return services

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        return result.returncode, result.stdout
    except subprocess.CalledProcessError as e:
        return e.returncode, e.stdout

def check_url(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code
    except (requests.RequestException, ValueError):
        return None

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('xml_path')
    args = parser.parse_args()

    services = parse_xml(args.xml_path)
    result = {}

    for name, config in services.items():
        command = config['command']
        exit_code, stdout = run_command(command)
        url = config['url']
        http_status = check_url(url)

        result[name] = {
            'exit_code': exit_code,
            'stdout': stdout.strip() if stdout else '',
            'http_status': http_status
        }

    print(json.dumps(result))

if __name__ == "__main__":
    sys.exit(main())

