import sys
import json
import subprocess
import requests
import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_services.py <config_file>")
        sys.exit(1)

    config_file = sys.argv[1]
    services_status = {}

    try:
        tree = ET.parse(config_file)
        root = tree.getroot()

        for service in root.findall('service'):
            name = service.get('name')
            command = service.find('command').text
            url = service.find('url').text

            # Run the command and get the exit code
            try:
                exit_code = subprocess.call(command, shell=True)
            except Exception as e:
                exit_code = -1  # Indicate an error in running the command

            # Request the URL and get the HTTP status code
            try:
                response = requests.get(url)
                http_status = response.status_code
            except requests.RequestException:
                http_status = None

            services_status[name] = {
                'exit_code': exit_code,
                'http_status': http_status
            }

    except ET.ParseError:
        print("Error parsing XML configuration file.")
        sys.exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        sys.exit(1)

    print(json.dumps(services_status))
    sys.exit(0)

if __name__ == '__main__':
    main()
